// Golden reflections update: 40 unique words, one softly illuminated word per click.
function createSpiritualWordDeck(random=Math.random){const words=["Faith", "Hope", "Love", "Grace", "Peace", "Compassion", "Gratitude", "Connection", "Presence", "Forgiveness", "Mercy", "Kindness", "Trust", "Courage", "Humility", "Patience", "Wisdom", "Wonder", "Awe", "Reverence", "Sacred", "Divine", "Spirit", "Soul", "Prayer", "Reflection", "Stillness", "Silence", "Purpose", "Meaning", "Belonging", "Unity", "Service", "Generosity", "Empathy", "Dignity", "Renewal", "Healing", "Acceptance", "Becoming"];let deck=[],last='';return()=>{if(!deck.length){deck=words.slice();for(let i=deck.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[deck[i],deck[j]]=[deck[j],deck[i]]}if(deck.at(-1)===last)[deck[0],deck[deck.length-1]]=[deck[deck.length-1],deck[0]]}last=deck.pop();return last}}
/* Fixed-pool particle dynamics: click waves, living trails and exact spring return. */
const gridBallPhysics={
step(b,dt){const gravity=20*Math.min(1,Math.abs(b.z)/45);b.vx+=(-b.x*15-b.vx*5.9)*dt;b.vy+=(-b.y*15-b.vy*5.9+gravity)*dt;b.vz+=(-b.z*19-b.vz*6.5)*dt;b.x+=b.vx*dt;b.y+=b.vy*dt;b.z+=b.vz*dt;if(Math.abs(b.x)+Math.abs(b.y)+Math.abs(b.z)+Math.abs(b.vx)+Math.abs(b.vy)+Math.abs(b.vz)<.025)b.x=b.y=b.z=b.vx=b.vy=b.vz=0},
impulse(b,dx,dy,strength){const d=Math.hypot(dx,dy)||1;b.vx+=dx/d*strength;b.vy+=dy/d*strength;b.vz+=strength*.35;b.vx=Math.max(-1600,Math.min(1600,b.vx));b.vy=Math.max(-1600,Math.min(1600,b.vy));b.vz=Math.min(1000,b.vz)}
};
(()=>{
const grid=document.getElementById('fireworkGrid');if(!grid)return;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,g=grid.getContext('2d'),sky=document.createElement('canvas');sky.className='firework-sky';sky.setAttribute('aria-hidden','true');document.body.append(sky);const ctx=sky.getContext('2d');
const nextWord=createSpiritualWordDeck(),wordStatus=document.createElement('span');wordStatus.setAttribute('role','status');wordStatus.setAttribute('aria-live','polite');wordStatus.style.cssText='position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap';grid.parentElement.append(wordStatus);
let balls=[],waves=[],trails=[],w=0,h=0,vw=0,vh=0,raf=0,last=0,time=0,visible=false,active=false,pointer={x:0,y:0},renderBalls=[],buckets=[[],[],[],[]];
function createPool(){const desired=Math.min(7200,Math.max(3200,Math.floor(w*h/100))),columns=Math.max(20,Math.round(Math.sqrt(desired*w/h))),rows=Math.ceil(desired/columns);balls=Array.from({length:columns*rows},(_,i)=>({u:(i%columns+.5)/columns,v:(Math.floor(i/columns)+.5)/rows,size:.55+i%7*.055,x:0,y:0,z:0,vx:0,vy:0,vz:0,phase:i*2.399963,light:0}));renderBalls=balls.map(()=>({x:0,y:0,r:0}))}
function measure(){const r=grid.getBoundingClientRect();w=r.width;h=r.height;vw=innerWidth;vh=innerHeight;const d=Math.min(devicePixelRatio||1,2);grid.width=Math.round(w*d);grid.height=Math.round(h*d);g.setTransform(d,0,0,d,0,0);sky.width=Math.round(vw*d);sky.height=Math.round(vh*d);ctx.setTransform(d,0,0,d,0,0);if(!balls.length)createPool();queue()}
function ignite(clientX,clientY){const r=grid.getBoundingClientRect(),x=(clientX??r.left+w/2)-r.left,y=(clientY??r.top+h/2)-r.top;for(const old of waves)if(old.wordRetired===undefined)old.wordRetired=old.age;const word=nextWord();wordStatus.textContent=word;waves.push({word,x,y,age:0,radius:0,max:Math.hypot(w,h)*.72,hits:new Uint8Array(balls.length)});if(waves.length>6)waves.shift();active=true;queue()}
function trail(e){const r=grid.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;pointer.x=x/w-.5;pointer.y=y/h-.5;const prev=trails.at(-1);if(!prev||Math.hypot(x-prev.x,y-prev.y)>5)trails.push({x,y,time});else{prev.x=x;prev.y=y;prev.time=time}if(trails.length>9)trails.shift();queue()}
function gold(){g.clearRect(0,0,w,h);for(const wave of waves){const power=Math.min(1,wave.age*7)*Math.exp(-wave.age*.86),radius=130+Math.min(100,wave.age*40);if(power<.004)continue;const light=g.createRadialGradient(wave.x,wave.y,0,wave.x,wave.y,radius);light.addColorStop(0,`rgba(255,223,141,${power*.66})`);light.addColorStop(.18,`rgba(233,181,77,${power*.3})`);light.addColorStop(.55,`rgba(157,109,35,${power*.11})`);light.addColorStop(1,'rgba(130,82,24,0)');g.fillStyle=light;g.fillRect(wave.x-radius,wave.y-radius,radius*2,radius*2);
const fadeIn=Math.min(1,Math.max(0,(wave.age-.08)/.18)),fadeOut=Math.min(1,Math.max(0,(1.15-wave.age)/.8)),retire=wave.wordRetired===undefined?1:Math.max(0,1-(wave.age-wave.wordRetired)/.45),alpha=fadeIn*fadeOut*retire;if(alpha>.001){g.save();const fontSize=Math.min(39,Math.max(23,w*.04));g.font=`italic ${fontSize}px Georgia, serif`;g.textAlign='center';g.textBaseline='middle';const half=g.measureText(wave.word).width/2+14,tx=Math.max(half,Math.min(w-half,wave.x)),ty=Math.max(fontSize,Math.min(h-fontSize,wave.y-(reduced?0:Math.min(13,wave.age*4))));g.shadowColor=`rgba(255,210,112,${alpha*.8})`;g.shadowBlur=18;g.fillStyle=`rgba(255,232,179,${alpha*.96})`;g.fillText(wave.word,tx,ty,Math.max(1,w-28));g.restore()}
}}
function frame(now){raf=0;const delta=Math.min(.04,Math.max(.001,(now-(last||now-16))/1000));last=now;time+=delta;const r=grid.getBoundingClientRect();ctx.clearRect(0,0,vw,vh);waves=waves.filter(wave=>wave.age<7);for(const wave of waves){wave.age+=delta;wave.radius=Math.min(wave.max,wave.age*(reduced?550:680))}trails=trails.filter(t=>time-t.time<.48);active=false;const breath=reduced?0:Math.sin(time*.8)*.004;
for(const bucket of buckets)bucket.length=0;
for(let i=0;i<balls.length;i++){const b=balls[i],homeX=b.u*w,homeY=b.v*h;let energy=0;
for(const wave of waves){const dx=homeX-wave.x,dy=homeY-wave.y,d=Math.hypot(dx,dy);if(!wave.hits[i]&&d<=wave.radius&&d<=wave.max){wave.hits[i]=1;const strength=(reduced?100:950)*Math.exp(-d/(wave.max*.42));gridBallPhysics.impulse(b,dx||.01,dy||.01,strength)}energy+=Math.exp(-Math.pow((d-wave.radius)/34,2))*Math.exp(-wave.age*.7)}
if(!reduced)for(let j=0;j<trails.length;j++){const a=trails[j],c=trails[Math.min(j+1,trails.length-1)];if(homeX<Math.min(a.x,c.x)-65||homeX>Math.max(a.x,c.x)+65||homeY<Math.min(a.y,c.y)-65||homeY>Math.max(a.y,c.y)+65)continue;const sx=c.x-a.x,sy=c.y-a.y,t=Math.max(0,Math.min(1,((homeX-a.x)*sx+(homeY-a.y)*sy)/(sx*sx+sy*sy||1))),dx=homeX-a.x-sx*t,dy=homeY-a.y-sy*t,d=Math.hypot(dx,dy);if(d<65&&d>1){const force=(1-d/65)*(1-(time-a.time)/.48);b.vx+=dx/d*force*950*delta;b.vy+=dy/d*force*950*delta;b.vz+=force*100*delta;energy+=force*.3;break}}
// Substeps keep the spring stable when a device misses a display frame.
if(b.x||b.y||b.z||b.vx||b.vy||b.vz){const steps=Math.ceil(delta/.009),dt=delta/steps;for(let k=0;k<steps;k++)gridBallPhysics.step(b,dt);}if(b.x||b.y||b.z)active=true;b.light+=(Math.min(1,energy+Math.abs(b.z)/100)-b.light)*(1-Math.exp(-delta*7));const flow=reduced?0:Math.sin(homeY*.012+time*.7)*1.5,depth=Math.max(.6,Math.min(1.7,1+b.z/550)),p=renderBalls[i];p.x=r.left+homeX+b.x+(homeX-w*.5)*breath+flow+pointer.x*b.z*.05;p.y=r.top+homeY+b.y+(homeY-h*.5)*breath+pointer.y*b.z*.04;p.r=b.size*depth;const bucket=Math.min(3,Math.floor(b.light*3.9));if(p.x>-8&&p.x<vw+8&&p.y>-8&&p.y<vh+8)buckets[bucket].push(i)}
if(visible||waves.length)gold();const shades=['rgba(151,184,223,.75)','rgba(167,202,238,.86)','rgba(196,219,239,.95)','rgba(244,223,161,.98)'];for(let k=0;k<4;k++){ctx.fillStyle=shades[k];ctx.beginPath();for(const i of buckets[k]){const p=renderBalls[i];ctx.moveTo(p.x+p.r,p.y);ctx.arc(p.x,p.y,p.r,0,Math.PI*2)}ctx.fill()}
if((visible&&!reduced)||active||waves.length||trails.length)queue();else last=0}
function queue(){if(!raf)raf=requestAnimationFrame(frame)}
grid.addEventListener('click',e=>ignite(e.clientX,e.clientY));grid.addEventListener('pointermove',trail);grid.addEventListener('pointerleave',()=>{trails=[];pointer={x:0,y:0}});grid.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();ignite()}});new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;last=0;if(visible)queue()},{rootMargin:'100px'}).observe(grid);addEventListener('resize',measure);addEventListener('scroll',queue,{passive:true});document.addEventListener('visibilitychange',()=>{last=0;if(!document.hidden)queue()});grid.setAttribute('aria-label','Breathing blue particle grid. Move across it to stir the balls. Click, tap or press Enter or Space for a golden shockwave and a spiritual reflection word; the same balls spring back to their original places.');measure();
})();
